from pathlib import Path
import json,html
OUT=Path(__file__).parent
r=json.loads((OUT/'delivery.json').read_text(encoding='utf-8'))
clips=[dict(id=x['id'],file=Path(x['file']).relative_to(OUT).as_posix(),status=x.get('pictureUsability',x.get('visualReview')),issues=x.get('integrationConditions',[]),duration=x['metadata']['duration']) for x in r['assembled']]
clips.sort(key=lambda x:['V32A','V33','V34','V35','V36','V37','V42'].index(x['id']))
source=r'''<!doctype html><meta charset="utf-8"><title>G5 七段候选合片审阅</title><style>body{background:#171b1a;color:#deded2;font:17px sans-serif;margin:24px}nav{display:flex;gap:8px;flex-wrap:wrap}button{font:inherit;background:#303e3a;color:inherit;border:1px solid #8b987f;padding:8px}video{width:100%;max-height:70vh;background:#000;margin-top:12px}pre{white-space:pre-wrap;line-height:1.6}#progress{padding:12px;color:#d7be8f}</style><h1>G5 七段候选合片</h1><p>七段当前文件已完成画面自查，均附接入条件，仍待用户review。声音未逐字听审。点击任一段后可从头或连续播放。</p><nav id="nav"></nav><video id="v" controls preload="metadata"></video><p><button id="play">从头播放</button> <button id="queue">从当前连续播放</button></p><div id="progress"></div><pre id="info"></pre><div id="done"></div><script>const clips=CLIPS;let current=0,continuous=false,done=[];const v=document.getElementById('v');function show(i){current=i;v.src=clips[i].file;document.getElementById('info').textContent=clips[i].id+' | '+clips[i].duration+'秒 | '+(clips[i].status==='usable-with-integration-condition'?'画面有接入条件可用':clips[i].status)+'\n接入条件：\n'+clips[i].issues.map(x=>'• '+x).join('\n')}clips.forEach((x,i)=>{let b=document.createElement('button');b.textContent=x.id;b.onclick=()=>{continuous=false;show(i)};document.getElementById('nav').append(b)});document.getElementById('play').onclick=()=>{v.currentTime=0;v.play()};document.getElementById('queue').onclick=()=>{continuous=true;v.currentTime=0;v.play()};v.ontimeupdate=()=>{document.getElementById('progress').textContent=clips[current].id+' '+v.currentTime.toFixed(2)+' / '+v.duration.toFixed(2)+'秒'};v.onended=()=>{done.push(clips[current].id);document.getElementById('done').textContent='本轮从头播放至尾：'+done.join('、');if(continuous&&current+1<clips.length){show(current+1);v.play()}};show(0);</script>'''
source=source.replace('CLIPS',json.dumps(clips,ensure_ascii=False))
(OUT/'合片审阅.html').write_text(source,encoding='utf-8')
print([(x['id'],x['file']) for x in clips])
